package org.apache.commons.math.stat;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.text.NumberFormat;
import java.util.*;
import java.util.Comparator;
import java.util.Iterator;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.math.stat.Frequency#addValue(Object)
 */
public class Frequency_addValue_TriageGen2Test {

    private Frequency frequency;

    @Before
    public void setUp() {
        frequency = new Frequency();
    }

    @Test
    public void testAddValueWithInteger() {
        Integer val = 10;
        frequency.addValue(val);
        assertEquals("Count for integer should be 1", 1L, frequency.getCount(val));
        assertEquals("Total sum frequency should be 1", 1L, frequency.getSumFreq());
    }

    @Test
    public void testAddValueWithDoubleAsComparable() {
        // Since addValue(Object) casts to Comparable<?>, we use Double
        Double val = 5.5;
        frequency.addValue(val);
        assertEquals("Count for double should be 1", 1L, frequency.getCount(val));
    }

    @Test
    public void testAddValueWithString() {
        String val = "test";
        frequency.addValue(val);
        assertEquals("Count for string should be 1", 1L, frequency.getCount(val));
    }

    @Test
    public void testAddValueMultipleTimes() {
        Integer val1 = 1;
        Integer val2 = 2;
        frequency.addValue(val1);
        frequency.addValue(val1);
        frequency.addValue(val2);

        assertEquals("Count for 1 should be 2", 2L, frequency.getCount(val1));
        assertEquals("Count for 2 should be 1", 1L, frequency.getCount(val2));
        assertEquals("Total sum frequency should be 3", 3L, frequency.getSumFreq());
    }

    @Test(expected = ClassCastException.class)
    public void testAddValueWithNonComparable() {
        // An object that does not implement Comparable
        Object nonComparable = new Object();
        frequency.addValue(nonComparable);
    }

    @Test
    public void testAddValueNull() {
        // Depending on implementation, null might be allowed if it's treated as a comparable or handled.
        // In many Frequency implementations, adding null might throw NPE during casting or internal sorting.
        // Given the cast (Comparable<?>) v, passing null is technically allowed by the cast but 
        // usually fails in the underlying map/tree.
        try {
            frequency.addValue(null);
        } catch (Exception e) {
            // If it throws an exception, it's a valid test for the behavior of the deprecated method
        }
    }
}
